function	app_tenant_visible(row_tenant uuid)	"CREATE OR REPLACE FUNCTION app_tenant_visible(row_tenant uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE\nAS $function$\n  SELECT row_tenant = NULLIF(current_setting('app.tenant_id', true), '')::uuid\n$function$\n"
function	audit_events_append_only()	"CREATE OR REPLACE FUNCTION audit_events_append_only()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', '\u003cschema\u003e'\nAS $function$\nBEGIN\n    RAISE EXCEPTION 'audit_events rows are append-only (% is not allowed)', TG_OP;\nEND;\n$function$\n"
function	audit_events_completion_guard()	"CREATE OR REPLACE FUNCTION audit_events_completion_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', '\u003cschema\u003e'\nAS $function$\nBEGIN\n    IF OLD.source \u003c\u003e 'http' OR OLD.outcome \u003c\u003e 'started' THEN\n        RAISE EXCEPTION 'audit_events rows are immutable after completion';\n    END IF;\n    IF NEW.source \u003c\u003e 'http' THEN\n        RAISE EXCEPTION 'audit completion cannot change source';\n    END IF;\n    IF NEW.outcome NOT IN ('succeeded', 'failed', 'denied', 'unknown') THEN\n        RAISE EXCEPTION 'audit completion requires a terminal outcome';\n    END IF;\n    IF NEW.completed_at IS NULL THEN\n        RAISE EXCEPTION 'audit completion requires completed_at';\n    END IF;\n    IF NEW.id IS DISTINCT FROM OLD.id\n        OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id\n        OR NEW.parent_id IS DISTINCT FROM OLD.parent_id\n        OR NEW.actor_id IS DISTINCT FROM OLD.actor_id\n        OR NEW.actor_type IS DISTINCT FROM OLD.actor_type\n        OR NEW.actor_role IS DISTINCT FROM OLD.actor_role\n        OR NEW.action IS DISTINCT FROM OLD.action\n        OR NEW.resource IS DISTINCT FROM OLD.resource\n        OR NEW.resource_id IS DISTINCT FROM OLD.resource_id\n        OR NEW.metadata IS DISTINCT FROM OLD.metadata\n        OR NEW.ip IS DISTINCT FROM OLD.ip\n        OR NEW.user_agent IS DISTINCT FROM OLD.user_agent\n        OR NEW.request_id IS DISTINCT FROM OLD.request_id\n        OR NEW.idempotency_key_hash IS DISTINCT FROM OLD.idempotency_key_hash\n        OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n        RAISE EXCEPTION 'audit completion may only change completion fields';\n    END IF;\n    -- status_code and error_code are completion fields, not intent fields:\n    -- the first non-NULL value is set once and can never change.\n    IF OLD.status_code IS NOT NULL AND NEW.status_code IS DISTINCT FROM OLD.status_code THEN\n        RAISE EXCEPTION 'audit completion cannot change status_code';\n    END IF;\n    IF OLD.error_code IS NOT NULL AND NEW.error_code IS DISTINCT FROM OLD.error_code THEN\n        RAISE EXCEPTION 'audit completion cannot change error_code';\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n"
function	files_track_storage_usage()	"CREATE OR REPLACE FUNCTION files_track_storage_usage()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', '\u003cschema\u003e'\nAS $function$\nDECLARE\n    delta BIGINT;\nBEGIN\n    IF TG_OP = 'INSERT' THEN\n        INSERT INTO files_storage_usage (tenant_id, user_id, bytes)\n        VALUES (NEW.tenant_id, NEW.user_id, NEW.size)\n        ON CONFLICT ON CONSTRAINT uq_files_storage_usage_tenant_user DO UPDATE\n        SET bytes = files_storage_usage.bytes + EXCLUDED.bytes;\n        RETURN NEW;\n    ELSIF TG_OP = 'DELETE' THEN\n        -- Remove the counter row when its last byte is released. This keeps\n        -- erasure and tenant purge from leaving a zero-byte user identifier\n        -- behind. A missing row is corruption, not a normal delete path.\n        DELETE FROM files_storage_usage\n        WHERE tenant_id = OLD.tenant_id\n          AND user_id = OLD.user_id\n          AND bytes = OLD.size;\n        IF NOT FOUND THEN\n            -- The first zero-byte file may already have removed the\n            -- zero-byte counter row. Further zero-byte deletes are still\n            -- valid and must not surface as corruption.\n            IF OLD.size = 0 THEN\n                RETURN OLD;\n            END IF;\n            UPDATE files_storage_usage\n            SET bytes = bytes - OLD.size\n            WHERE tenant_id = OLD.tenant_id AND user_id = OLD.user_id;\n            IF NOT FOUND THEN\n                RAISE EXCEPTION 'files_storage_usage row missing for tenant % user %',\n                    OLD.tenant_id, OLD.user_id;\n            END IF;\n        END IF;\n        RETURN OLD;\n    ELSE\n        IF NEW.tenant_id \u003c\u003e OLD.tenant_id OR NEW.user_id \u003c\u003e OLD.user_id THEN\n            INSERT INTO files_storage_usage (tenant_id, user_id, bytes)\n            VALUES (OLD.tenant_id, OLD.user_id, -OLD.size)\n            ON CONFLICT ON CONSTRAINT uq_files_storage_usage_tenant_user DO UPDATE\n            SET bytes = files_storage_usage.bytes + EXCLUDED.bytes;\n            INSERT INTO files_storage_usage (tenant_id, user_id, bytes)\n            VALUES (NEW.tenant_id, NEW.user_id, NEW.size)\n            ON CONFLICT ON CONSTRAINT uq_files_storage_usage_tenant_user DO UPDATE\n            SET bytes = files_storage_usage.bytes + EXCLUDED.bytes;\n            RETURN NEW;\n        END IF;\n        delta := NEW.size - OLD.size;\n        IF delta = 0 THEN\n            RETURN NEW;\n        END IF;\n        INSERT INTO files_storage_usage (tenant_id, user_id, bytes)\n        VALUES (NEW.tenant_id, NEW.user_id, delta)\n        ON CONFLICT ON CONSTRAINT uq_files_storage_usage_tenant_user DO UPDATE\n        SET bytes = files_storage_usage.bytes + EXCLUDED.bytes;\n        RETURN NEW;\n    END IF;\nEND;\n$function$\n"
function	protect_last_owner()	"CREATE OR REPLACE FUNCTION protect_last_owner()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', '\u003cschema\u003e'\nAS $function$\nDECLARE\n    target_tenant UUID;\n    owner_role UUID;\n    operational BOOLEAN;\nBEGIN\n    target_tenant := OLD.tenant_id;\n    SELECT id INTO owner_role\n    FROM roles WHERE tenant_id IS NULL AND scope = 'tenant' AND key = 'owner';\n\n    IF TG_TABLE_NAME = 'membership_roles' THEN\n        IF TG_OP = 'UPDATE' AND NEW.role_id = OLD.role_id\n           AND NEW.tenant_id = OLD.tenant_id AND NEW.user_id = OLD.user_id THEN\n            RETURN NEW;\n        END IF;\n        IF OLD.role_id \u003c\u003e owner_role THEN\n            RETURN COALESCE(NEW, OLD);\n        END IF;\n    ELSE\n        IF OLD.status \u003c\u003e 'active' THEN\n            RETURN COALESCE(NEW, OLD);\n        END IF;\n        IF TG_OP = 'UPDATE' AND NEW.status = 'active' AND NEW.tenant_id = OLD.tenant_id THEN\n            RETURN NEW;\n        END IF;\n        IF NOT EXISTS (\n            SELECT 1 FROM membership_roles\n            WHERE tenant_id = OLD.tenant_id AND user_id = OLD.user_id\n              AND role_id = owner_role\n        ) THEN\n            RETURN COALESCE(NEW, OLD);\n        END IF;\n    END IF;\n\n    IF NOT EXISTS (\n        SELECT 1 FROM memberships m\n        JOIN users u ON u.id = m.user_id\n        WHERE m.tenant_id = OLD.tenant_id AND m.user_id = OLD.user_id\n          AND m.status = 'active' AND u.status = 'active'\n    ) THEN\n        RETURN COALESCE(NEW, OLD);\n    END IF;\n\n    SELECT status IN ('trialing', 'active') INTO operational\n    FROM tenants WHERE id = target_tenant;\n    IF NOT COALESCE(operational, FALSE) THEN\n        RETURN COALESCE(NEW, OLD);\n    END IF;\n\n    PERFORM pg_advisory_xact_lock(hashtextextended('identity.last_owner:' || target_tenant, 0));\n\n    PERFORM 1\n    FROM membership_roles mr\n    JOIN memberships m ON m.tenant_id = mr.tenant_id AND m.user_id = mr.user_id\n    JOIN users u ON u.id = m.user_id\n    WHERE mr.tenant_id = target_tenant\n      AND mr.role_id = owner_role\n      AND mr.user_id \u003c\u003e OLD.user_id\n      AND m.status = 'active'\n      AND u.status = 'active'\n    LIMIT 1\n    FOR UPDATE OF mr;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'cannot remove the last owner' USING ERRCODE = 'LO001';\n    END IF;\n    RETURN COALESCE(NEW, OLD);\nEND;\n$function$\n"
function	update_updated_at()	"CREATE OR REPLACE FUNCTION update_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', '\u003cschema\u003e'\nAS $function$\nBEGIN\n    NEW.updated_at = NOW();\n    RETURN NEW;\nEND;\n$function$\n"
function	validate_invitation_role()	"CREATE OR REPLACE FUNCTION validate_invitation_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', '\u003cschema\u003e'\nAS $function$\nDECLARE\n    role_row roles%ROWTYPE;\nBEGIN\n    SELECT * INTO role_row FROM roles WHERE id = NEW.role_id;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'role does not exist';\n    END IF;\n    IF role_row.scope \u003c\u003e 'tenant' THEN\n        RAISE EXCEPTION 'invitation roles must be tenant-scoped';\n    END IF;\n    IF role_row.tenant_id IS NOT NULL AND role_row.tenant_id \u003c\u003e NEW.tenant_id THEN\n        RAISE EXCEPTION 'role belongs to another tenant';\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n"
function	validate_membership_role()	"CREATE OR REPLACE FUNCTION validate_membership_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', '\u003cschema\u003e'\nAS $function$\nDECLARE\n    role_row roles%ROWTYPE;\nBEGIN\n    SELECT * INTO role_row FROM roles WHERE id = NEW.role_id;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'role does not exist';\n    END IF;\n    IF role_row.scope \u003c\u003e 'tenant' THEN\n        RAISE EXCEPTION 'membership roles must be tenant-scoped';\n    END IF;\n    IF role_row.tenant_id IS NOT NULL AND role_row.tenant_id \u003c\u003e NEW.tenant_id THEN\n        RAISE EXCEPTION 'role belongs to another tenant';\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n"
function	validate_platform_role()	"CREATE OR REPLACE FUNCTION validate_platform_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', '\u003cschema\u003e'\nAS $function$\nDECLARE\n    role_row roles%ROWTYPE;\nBEGIN\n    SELECT * INTO role_row FROM roles WHERE id = NEW.role_id;\n    IF NOT FOUND OR role_row.scope \u003c\u003e 'platform' OR role_row.tenant_id IS NOT NULL THEN\n        RAISE EXCEPTION 'platform assignments require a platform-scoped role';\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n"
function	validate_role_permission()	"CREATE OR REPLACE FUNCTION validate_role_permission()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', '\u003cschema\u003e'\nAS $function$\nDECLARE\n    owner_tenant UUID;\nBEGIN\n    SELECT tenant_id INTO owner_tenant FROM roles WHERE id = NEW.role_id;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'role does not exist or is not visible to the caller';\n    END IF;\n    IF owner_tenant IS NOT NULL AND NEW.permission_key LIKE 'platform:%' THEN\n        RAISE EXCEPTION 'tenant roles cannot hold platform permissions';\n    END IF;\n    RETURN NEW;\nEND;\n$function$\n"
